create table if not exists public.source_records (id text primary key, source_file_id uuid not null references public.source_files(id), dataset text not null, company_name text, uniform_number text, domain text, title text, summary text, source_url text, raw jsonb not null, indexed_at timestamptz not null default now()); alter table public.source_records enable row level security; create policy source_records_public_read on public.source_records for select to anon, authenticated using (true); grant select on public.source_records to anon, authenticated; grant all on public.source_records to service_role; create index source_records_uniform_idx on public.source_records(uniform_number); create index source_records_name_idx on public.source_records(company_name); create index source_records_domain_idx on public.source_records(domain); create index source_records_file_idx on public.source_records(source_file_id);;
